const ctx = $input.first().json;
const to = ctx.as_of;
const from = new Date(new Date(to + 'T00:00:00Z').getTime() - 3 * 86400000).toISOString().slice(0, 10);
return ctx.tickers.filter(t => !(ctx.benchmarks || []).includes(t)).map(t => ({ json: { ticker: t, from, to, run_id: ctx.run_id } }));

// One full response per ticker request. Ticker = the queried symbol; usage = one ledger row per call.
const ctx = $('When called').first().json;
const reqs = $('One item per ticker').all();
const byId = new Map(), usage = [];
$input.all().forEach((it, i) => {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = (pi != null && typeof pi === 'object' ? pi.item : pi) ?? i;
  const ticker = reqs[idx] ? reqs[idx].json.ticker : null;
  const code = Number(it.json.statusCode) || null;
  let body = it.json.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const ok = code === 200 && Array.isArray(body) && !!ticker;
  usage.push({ ticker, status: ok ? 'ok' : (code === 429 ? 'quota_skip' : 'error'), http_code: code, n: ok ? body.length : 0 });
  if (!ok) return;
  for (const a of body) {
    if (!a || !a.id || !a.headline) continue;
    const id = 'fh-' + ticker + '-' + a.id;
    byId.set(id, { id, ticker, published_at: new Date(a.datetime * 1000).toISOString(), source: 'finnhub', headline: String(a.headline).slice(0, 500), url: a.url, summary: String(a.summary || '').slice(0, 2000), sentiment: null, sentiment_src: null });
  }
});
const rows = [...byId.values()];
const failed = usage.filter(u => u.status !== 'ok');
return [{ json: { run_id: ctx.run_id, rows, count: rows.length, usage, calls: usage.length, failed: failed.length, failed_tickers: failed.map(u => u.ticker) } }];

// Alpha Vantage: 25 calls/day and a multi-ticker query is AND, not OR.
// Plan: 4 topic calls (broad coverage), per-ticker calls for holdings, and a rotating slice of the rest.
const ctx = $input.first().json;
const skip = new Set(ctx.benchmarks || []);
const all = ctx.tickers.filter(t => !skip.has(t));
const holdings = ctx.holdings || [];
const rest = all.filter(t => !holdings.includes(t));
const from = new Date(new Date(ctx.as_of + 'T00:00:00Z').getTime() - 3 * 86400000);
const time_from = from.toISOString().slice(0, 10).replace(/-/g, '') + 'T0000';
const base = 'https://www.alphavantage.co/query?function=NEWS_SENTIMENT&sort=LATEST&limit=1000&time_from=' + time_from;
const budget = Number(ctx.av_budget || 22);
const out = [];
for (const topic of ['technology', 'manufacturing', 'energy_transportation', 'financial_markets']) out.push({ json: { kind: 'topic', key: topic, url: base + '&topics=' + topic, run_id: ctx.run_id } });
for (const t of holdings) out.push({ json: { kind: 'ticker', key: t, url: base + '&tickers=' + t, run_id: ctx.run_id } });
const spare = Math.max(0, budget - out.length);
const day = Math.floor(new Date(ctx.as_of + 'T00:00:00Z').getTime() / 86400000);
const start = rest.length ? (day * spare) % rest.length : 0;
for (let i = 0; i < Math.min(spare, rest.length); i++) { const t = rest[(start + i) % rest.length]; out.push({ json: { kind: 'ticker', key: t, url: base + '&tickers=' + t, run_id: ctx.run_id } }); }
return out;

// One row per (article, ticker) with AV's per-ticker sentiment. relevance < 0.1 is noise.
const ctx = $('When called').first().json;
const want = new Set(ctx.tickers);
const rows = [];
let calls = 0, throttled = 0, errors = 0;
const plan = $('AV query plan').all(), usage = [];
const h = (s) => { let x = 5381; for (const c of s) x = ((x << 5) + x + c.charCodeAt(0)) >>> 0; return x.toString(36); };
$input.all().forEach((it, i) => {
  calls++;
  const j = it.json || {};
  const key = plan[i] ? plan[i].json.key : null;
  if (j.Information || j.Note) { throttled++; usage.push({ ticker: key, status: 'quota_skip', http_code: 200 }); return; }
  if (!Array.isArray(j.feed)) { errors++; usage.push({ ticker: key, status: 'error', http_code: null }); return; }
  usage.push({ ticker: key, status: 'ok', http_code: 200 });
  for (const a of j.feed || []) {
    const ts = a.time_published; // YYYYMMDDTHHMMSS
    const iso = ts ? `${ts.slice(0,4)}-${ts.slice(4,6)}-${ts.slice(6,8)}T${ts.slice(9,11)}:${ts.slice(11,13)}:${ts.slice(13,15)}Z` : null;
    for (const s of a.ticker_sentiment || []) {
      if (!want.has(s.ticker) || Number(s.relevance_score) < 0.1) continue;
      rows.push({ id: 'av-' + s.ticker + '-' + h(a.url || a.title), ticker: s.ticker, published_at: iso, source: 'alphavantage', headline: String(a.title || '').slice(0, 500), url: a.url, summary: String(a.summary || '').slice(0, 2000), sentiment: Math.round(Number(s.ticker_sentiment_score) * 1000) / 1000, sentiment_src: 'av', raw: { relevance: s.relevance_score, overall: a.overall_sentiment_score, src: a.source } });
    }
  }
});
// Same article can arrive from a topic call and a ticker call: keep one row per id (highest relevance).
const byId = new Map();
for (const r of rows) { const prev = byId.get(r.id); if (!prev || Number(r.raw.relevance) > Number(prev.raw.relevance)) byId.set(r.id, r); }
const uniq = [...byId.values()];
return [{ json: { run_id: ctx.run_id, rows: uniq, count: uniq.length, raw_count: rows.length, calls, throttled, errors, usage } }];
